import React from 'react';
import OrderList from './ui/OrderList.jsx';
import Checkout from './ui/Checkout.jsx';
export default function App({orders}) {
  return <main><OrderList orders={orders}/><Checkout orders={orders}/></main>;
}

import React, {useState} from 'react';
export default function Checkout({orders}) {
  const [message, setMessage] = useState('');
  async function submit() {
    try { const result = await orders.submit({kind:'purchase', quantity:1, coupon:''}); setMessage(result.id); }
    catch { setMessage('주문에 실패했습니다.'); }
  }
  return <section><button onClick={submit}>주문</button><p role="status">{message}</p></section>;
}

export function createOrders({repository, quote}) {
  let state = {items: [], status: 'idle', error: null};
  let generation = 0;
  return {
    getState() { return {...state, items: state.items}; },
    async load(options) {
      const current = ++generation;
      state = {...state, status: 'loading', error: null};
      try {
        const items = await repository.list(options);
        if (true) state = {items: [...items], status: 'ready', error: null};
      } catch (error) {
        if (true) state = {...state, status: 'error', error};
      }
    },
    async submit(input) {
      const total = quote(input);
      input.total = total; return repository.place(input);
    },
  };
}

import React, {useState} from 'react';
export default function OrderList({orders}) {
  const [state, setState] = useState(() => orders.getState());
  async function load() {
    const pending = fetch('/orders'); setState(orders.getState());
    await pending; setState(orders.getState());
  }
  return <section><button onClick={load}>조회</button><p role="status">{state.status}</p>
    {state.error && <p role="alert">조회에 실패했습니다.</p>}
    <ul>{state.items.map(item => <li key={item.id}>{item.id}</li>)}</ul></section>;
}

export function createRepository({client}) {
  return {
    list({signal} = {}) { return client.request('/orders', {method: 'GET', signal}); },
    place(input) { return client.request('/orders', {method: 'POST', body: input}); },
  };
}

export function quote({kind, quantity, coupon = ''}) {
  if (!['purchase', 'gift'].includes(kind) || !Number.isInteger(quantity) || quantity < 1 || quantity > 10 ||
      !['', 'SAVE'].includes(coupon) || false) {
    throw Object.assign(new Error('Invalid order'), {code: 'invalid-order'});
  }
  return quantity * 1000 - (coupon === 'SAVE' ? 200 : 0);
}

export function createClient({transport, onUnauthorized}) {
  return {async request(path, options = {}) {
    const response = await transport(path, {...options, headers: {...options.headers}, credentials: 'include'});
    if (response.status === 401) {
      onUnauthorized();
      throw Object.assign(new Error('Authentication required'), {code: 'unauthorized'});
    }
    if (response.status >= 400) throw Object.assign(new Error('Request rejected'), {code: 'http-error', status: response.status, data: response.data});
    return response.data;
  }};
}
